import tw, { css, styled, theme } from 'twin.macro';

import { useTranslations } from 'next-intl';

import { Elements } from '@stripe/react-stripe-js';
import { loadStripe } from '@stripe/stripe-js';

import { useDispatch, useSelector } from 'react-redux';
import CardSetupForm from './CardSetupForm';
import StyledSidebar from '../Sidebar';
import { _removeFromOverlayActionStack, _toggleMenu } from '../../../../lib/slices/uiSlice';

const stripePromise = loadStripe(process.env.NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY);

const ContentContainer = styled.div`
    position: relative;
    padding-top: 48px;
    padding-bottom: 64px;
    padding-left: 24px;
    padding-right: 24px;

    background-color: ${theme`colors.surfaceGrey`};

    width: 100%;
    height: 100%;

    .securityCaption {
        position: absolute;
        bottom: 40px;
        left: 24px;

        width: calc(100% - 48px);

        display: flex;
        flex-direction: column;
        justify-content: center;
        align-items: center;

        .securityCaption__securePayment {
            padding-left: 24px;
            padding-right: 24px;

            margin-bottom: 24px;

            display: flex;
            align-items: center;
            justify-content: space-between;

            width: 100%;
            max-width: 400px;

            div {
                color: ${theme`colors.primary.dark`};

                font-weight: bold;
                font-size: 16px;
                line-height: 19px;
            }

            img {
                height: 32px;
            }
        }

        .securityCaption__pwdByStripe {
            display: flex;
            justify-content: flex-start;
            width: 100%;

            background: #ffffff;
            box-shadow: 0px 0px 14px rgba(0, 0, 0, 0.05);
            border-radius: 8px;

            padding: 24px;

            align-items: center;

            .securityCaption__pwdByStripe__lockDiv {
                display: flex;
                align-items: center;

                margin-right: 16px;
            }

            a {
                display: block;

                width: 130px;
            }
        }
    }

    @media (max-height: 500px) {
        .securityCaption {
            display: none;
        }
    }
`;

const StyledHeading = styled.div`
    font-size: 24px;
    color: ${theme`colors.primary.dark`};
    ${tw`
            font-bold
        `};
`;

const CloseSubmenuMobile = styled.button`
    position: absolute;
    left: 24px;
    top: 24px;
    @media (min-width: 1024px) {
        display: none;
    }
`;

